from __future__ import annotations

import base64
import subprocess

PATCH_B64 = "";


def main() -> None:
    patch = base64.b64decode(PATCH_B64)
    subprocess.run(["git", "apply", "--check", "-"], input=patch, check=True)
    subprocess.run(["git", "apply", "-"], input=patch, check=True)


if __name__ == "__main__":
    main()
